contracts/CreationController.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {ProjectToken} from "./ProjectToken.sol";
import {SwarmCollection} from "./SwarmCollection.sol";
interface IArtifactVerifier {
    function attestor() external view returns (address);
    function verify(
        uint256 id,
        bytes32 requestId,
        bytes32 hash,
        bytes calldata proof
    ) external view returns (bool);
    function verifyFinality(uint256 cutoff, bytes calldata proof) external view returns (bool);
    function verifyRecovery(
        uint256 id,
        bytes32 requestId,
        uint256 attempt,
        uint256 amount,
        address paymentRecipient,
        bytes calldata proof
    ) external view returns (bool);
}
interface ICompletionRewards {
    function fund(uint256 amount) external;
}
contract CreationController is Ownable2Step, ReentrancyGuard {
    using SafeERC20 for IERC20;
    struct Funding {
        uint256 cumulative;
        uint64 blockNumber;
        uint64 time;
    }
    struct Job {
        uint64 cutoff;
        uint64 time;
        uint256 cursor;
        uint256 count;
        address winner;
        uint256 bestScore;
        bytes32 requestId;
        bool selected;
        bool paid;
        bool finalized;
    }
    IERC20 public immutable imd;
    ProjectToken public immutable token;
    SwarmCollection public immutable collection;
    IArtifactVerifier public immutable verifier;
    address public immutable operator;
    address public immutable paymentRecipient;
    uint256 public immutable jobBudget;
    uint256 public immutable settlementBlocks;
    bytes32 public immutable baseHash;
    address public immutable recoveryRecipient;
    uint256 public constant MIGRATION_DELAY = 2 days;
    bool public paused;
    bool public retired;
    uint256 public withdrawalAvailableAt;
    bytes32 public withdrawalReason;
    uint256 public totalFunded;
    uint256 public nextJobId = 1;
    address public feeRouter;
    Funding[] private localFunding;
    CreationController public predecessor;
    uint256 public inheritedFundingCount;
    uint256 public migrationStartId;
    uint256 public migrationDepth;
    bool public migrationImported;
    uint256 public recoveredAmount;
    mapping(uint256 => Job) private localJobs;
    mapping(address => bool) private localAllocated;
    mapping(bytes32 => bool) private localUsedRequests;
    mapping(uint256 => uint256) public attempts;
    mapping(uint256 => uint256) private localFundingIndex;
    function fundingIndex(uint256 id) public view returns(uint256) {
        if (id < migrationStartId && address(predecessor) != address(0)) return predecessor.fundingIndex(id);
        return localFundingIndex[id];
    }
    event CreationFunded(uint256 amount, uint256 cumulative);
    event JobOpened(uint256 indexed id, uint256 cutoff, uint256 time);
    event RecipientSelected(uint256 indexed id, address indexed winner, uint256 score);
    event JobPayment(uint256 indexed id, uint256 amount, address recipient);
    event WorkRequested(uint256 indexed id, bytes32 requestId);
    event JobMinted(uint256 indexed id, bytes32 requestId, bytes32 artifactHash);
    event JobRecovered(
        uint256 indexed id,
        bytes32 oldRequestId,
        uint256 attempt,
        uint256 refundedBudget,
        address refundPayer
    );
    event SnapshotAdvanced(uint256 indexed id, uint256 oldCutoff, uint256 newCutoff);
    event EmergencyPaused(address indexed administrator);
    event CreationResumed();
    event WithdrawalScheduled(address indexed recipient, uint256 availableAt, bytes32 reason);
    event WithdrawalCancelled();
    event CreationFundsRecovered(address indexed recipient, uint256 amount, bytes32 reason);
    modifier whenActive() {
        require(
            !paused && !retired && (address(predecessor) == address(0) || migrationImported),
            "creation paused or retired"
        );
        _;
    }
    constructor(
        address admin,
        IERC20 money,
        ProjectToken project,
        SwarmCollection nft,
        IArtifactVerifier proofVerifier,
        address swarmOperator,
        address payTo,
        uint256 budget,
        uint256 delayBlocks,
        bytes32 firstArtHash
    ) Ownable(admin) {
        require(
            address(money) != address(0) &&
                address(project) != address(0) &&
                address(nft) != address(0) &&
                address(proofVerifier) != address(0),
            "contracts"
        );
        address signer = proofVerifier.attestor();
        require(
            signer != address(0) && signer != swarmOperator && signer != admin,
            "independent attestor required"
        );
        require(
            swarmOperator != address(0) &&
                swarmOperator != admin &&
                payTo != address(0) &&
                budget > 0 &&
                delayBlocks > 0 &&
                firstArtHash != bytes32(0),
            "configuration"
        );
        imd = money;
        token = project;
        collection = nft;
        verifier = proofVerifier;
        operator = swarmOperator;
        paymentRecipient = payTo;
        jobBudget = budget;
        settlementBlocks = delayBlocks;
        baseHash = firstArtHash;
        recoveryRecipient = admin;
    }
    // Creation reserves only. Already allocated NFT rewards and pool liquidity are outside this contract.
    function emergencyPause() external onlyOwner {
        require(!paused && !retired && collection.totalSupply() < 1000, "creation phase");
        paused = true;
        emit EmergencyPaused(msg.sender);
    }
    function resumeCreation() external onlyOwner {
        require(
            paused &&
                !retired &&
                withdrawalAvailableAt == 0 &&
                (address(predecessor) == address(0) ||
                    (migrationImported && collection.controller() == address(this))),
            "migration pending or retired"
        );
        paused = false;
        emit CreationResumed();
    }
    function scheduleWithdrawal(bytes32 reason) external onlyOwner {
        require(
            paused && !retired && withdrawalAvailableAt == 0 && reason != bytes32(0),
            "withdrawal state"
        );
        withdrawalAvailableAt = block.timestamp + MIGRATION_DELAY;
        withdrawalReason = reason;
        emit WithdrawalScheduled(recoveryRecipient, withdrawalAvailableAt, reason);
    }
    function cancelWithdrawal() external onlyOwner {
        require(!retired && withdrawalAvailableAt != 0, "no pending withdrawal");
        withdrawalAvailableAt = 0;
        withdrawalReason = bytes32(0);
        emit WithdrawalCancelled();
    }
    function withdrawCreationFunds() external onlyOwner nonReentrant {
        require(
            paused &&
                !retired &&
                withdrawalAvailableAt != 0 &&
                block.timestamp >= withdrawalAvailableAt &&
                collection.totalSupply() < 1000,
            "withdrawal delay or phase"
        );
        retired = true;
        uint256 amount = imd.balanceOf(address(this));
        recoveredAmount = amount;
        imd.safeTransfer(recoveryRecipient, amount);
        emit CreationFundsRecovered(recoveryRecipient, amount, withdrawalReason);
    }
    event MigrationPrepared(address indexed predecessor);
    event MigrationImported(address indexed predecessor, uint256 nextNft, uint256 recoveredFunds);
    function allocated(address account) public view returns (bool) {
        return
            localAllocated[account] ||
            (address(predecessor) != address(0) && predecessor.allocated(account));
    }
    function usedRequests(bytes32 request) public view returns (bool) {
        return
            localUsedRequests[request] ||
            (address(predecessor) != address(0) && predecessor.usedRequests(request));
    }
    function jobs(uint256 id) external view returns (Job memory) {
        if (address(predecessor) != address(0) && migrationImported && id < migrationStartId)
            return predecessor.jobs(id);
        return localJobs[id];
    }
    function fundingLength() public view returns (uint256) {
        return inheritedFundingCount + localFunding.length;
    }
    function funding(uint256 index) public view returns (Funding memory) {
        if (index < inheritedFundingCount) return predecessor.funding(index);
        return localFunding[index - inheritedFundingCount];
    }
    // A replacement is inert until the official fee router completes its delayed atomic handover.
    function prepareMigration(CreationController previous) external onlyOwner {
        require(
            address(predecessor) == address(0) &&
                totalFunded == 0 &&
                nextJobId == 1 &&
                localFunding.length == 0 &&
                address(previous) != address(this),
            "fresh replacement"
        );
        require(
            previous.paused() &&
                address(previous.token()) == address(token) &&
                address(previous.collection()) == address(collection) &&
                address(previous.imd()) == address(imd) &&
                previous.recoveryRecipient() == recoveryRecipient &&
                previous.operator() == operator &&
                previous.paymentRecipient() == paymentRecipient &&
                previous.jobBudget() == jobBudget &&
                previous.settlementBlocks() == settlementBlocks &&
                previous.baseHash() == baseHash &&
                previous.migrationDepth() < 8,
            "migration compatibility"
        );
        require(
            collection.totalSupply() < 1000 && collection.controller() == address(previous),
            "current controller"
        );
        predecessor = previous;
        migrationDepth = previous.migrationDepth() + 1;
        paused = true;
        emit MigrationPrepared(address(previous));
    }
    function importMigration() external nonReentrant {
        require(
            msg.sender == feeRouter &&
                paused &&
                !retired &&
                address(predecessor) != address(0) &&
                !migrationImported &&
                predecessor.retired() &&
                collection.controller() == address(predecessor),
            "migration import"
        );
        nextJobId = predecessor.nextJobId();
        require(nextJobId == collection.totalSupply() + 1, "mint sequence");
        totalFunded = predecessor.totalFunded();
        inheritedFundingCount = predecessor.fundingLength();
        migrationStartId = nextJobId;
        localJobs[nextJobId] = predecessor.jobs(nextJobId);
        attempts[nextJobId] = predecessor.attempts(nextJobId);
        localFundingIndex[nextJobId] = predecessor.fundingIndex(nextJobId);
        uint256 amount = predecessor.recoveredAmount();
        uint256 balance = imd.balanceOf(address(this));
        if (amount > 0) imd.safeTransferFrom(recoveryRecipient, address(this), amount);
        require(imd.balanceOf(address(this)) - balance == amount, "full migration funding");
        migrationImported = true;
        emit MigrationImported(address(predecessor), nextJobId, amount);
    }
    function activateMigration() external {
        require(
            msg.sender == feeRouter &&
                migrationImported &&
                paused &&
                !retired &&
                withdrawalAvailableAt == 0 &&
                collection.controller() == address(this),
            "migration activation"
        );
        paused = false;
        emit CreationResumed();
    }
    function configureRouter(address router) external onlyOwner {
        require(feeRouter == address(0) && router.code.length > 0, "router");
        feeRouter = router;
    }
    function deposit(uint256 amount) external nonReentrant {
        require(
            msg.sender == feeRouter &&
                token.eligibilitySealed() &&
                collection.totalSupply() < 1000 &&
                amount > 0,
            "funding"
        );
        require(
            !retired && (address(predecessor) == address(0) || migrationImported),
            "retired or inert controller"
        );
        uint256 beforeBalance = imd.balanceOf(address(this));
        imd.safeTransferFrom(msg.sender, address(this), amount);
        require(imd.balanceOf(address(this)) - beforeBalance == amount, "received");
        totalFunded += amount;
        localFunding.push(Funding(totalFunded, uint64(block.number), uint64(block.timestamp)));
        emit CreationFunded(amount, totalFunded);
    }
    // Anyone can open/scan. The cutoff is the earliest funding checkpoint meeting this job's cumulative budget.
    function openNextJob() external whenActive {
        uint256 id = nextJobId;
        require(id <= 1000 && localJobs[id].cutoff == 0 && totalFunded >= id * jobBudget, "job");
        uint256 lo = id > 1 ? fundingIndex(id - 1) : 0;
        uint256 hi = fundingLength();
        while (lo < hi) {
            uint256 mid = (lo + hi) / 2;
            if (funding(mid).cumulative < id * jobBudget) lo = mid + 1;
            else hi = mid;
        }
        Funding memory point = funding(lo);
        localFundingIndex[id] = lo;
        localJobs[id].cutoff = point.blockNumber;
        localJobs[id].time = point.time;
        emit JobOpened(id, point.blockNumber, point.time);
    }
    function confirmFinality(bytes calldata proof) external whenActive {
        Job storage job = localJobs[nextJobId];
        require(
            job.cutoff > 0 &&
                !job.finalized &&
                block.number > uint256(job.cutoff) + settlementBlocks,
            "settlement"
        );
        require(verifier.verifyFinality(job.cutoff, proof), "finality proof");
        job.finalized = true;
    }
    // An exhausted snapshot can move only to the earliest later funding block, never to an arbitrary cutoff.
    function advanceEmptySnapshot() external whenActive {
        uint256 id = nextJobId;
        Job storage job = localJobs[id];
        require(
            job.cutoff > 0 &&
                job.finalized &&
                !job.selected &&
                job.winner == address(0) &&
                job.count == token.holderCountAt(job.cutoff) &&
                job.cursor == job.count,
            "snapshot not exhausted"
        );
        uint256 lo = localFundingIndex[id] + 1;
        uint256 hi = fundingLength();
        while (lo < hi) {
            uint256 mid = (lo + hi) / 2;
            if (funding(mid).blockNumber <= job.cutoff) lo = mid + 1;
            else hi = mid;
        }
        require(lo < fundingLength(), "await next funding snapshot");
        Funding memory point = funding(lo);
        uint256 old = job.cutoff;
        localFundingIndex[id] = lo;
        job.cutoff = point.blockNumber;
        job.time = point.time;
        job.cursor = 0;
        job.count = 0;
        job.bestScore = 0;
        job.finalized = false;
        emit SnapshotAdvanced(id, old, point.blockNumber);
        emit JobOpened(id, point.blockNumber, point.time);
    }
    // Replacement authorization is bound to this exact attempt, and another budget must be returned first.
    function recoverJob(bytes calldata proof) external nonReentrant {
        require(!retired, "retired controller");
        uint256 id = nextJobId;
        Job storage job = localJobs[id];
        require(id <= 1000 && job.selected && job.paid, "paid job required");
        uint256 attempt = attempts[id];
        bytes32 oldRequest = job.requestId;
        require(
            verifier.verifyRecovery(id, oldRequest, attempt, jobBudget, paymentRecipient, proof),
            "recovery proof"
        );
        uint256 beforeBalance = imd.balanceOf(address(this));
        imd.safeTransferFrom(msg.sender, address(this), jobBudget);
        require(imd.balanceOf(address(this)) - beforeBalance == jobBudget, "full refund required");
        attempts[id] = attempt + 1;
        job.paid = false;
        job.requestId = bytes32(0);
        emit JobRecovered(id, oldRequest, attempt + 1, jobBudget, msg.sender);
    }
    function scan(uint256 limit) external whenActive {
        Job storage job = localJobs[nextJobId];
        require(
            job.cutoff > 0 &&
                job.finalized &&
                !job.selected &&
                block.number > uint256(job.cutoff) + settlementBlocks,
            "settlement"
        );
        require(limit > 0 && limit <= 250, "batch");
        uint256 count = token.holderCountAt(job.cutoff);
        job.count = count;
        uint256 end = job.cursor + limit;
        if (end > count) end = count;
        for (uint256 i = job.cursor; i < end; i++) {
            address candidate = token.holders(i);
            if (token.excluded(candidate) || allocated(candidate)) continue;
            (uint256 score, uint256 balance) = token.scoreAt(candidate, job.cutoff, job.time);
            if (balance < token.MINIMUM_HOLDER_BALANCE()) continue;
            if (
                job.winner == address(0) ||
                score > job.bestScore ||
                (score == job.bestScore && uint160(candidate) < uint160(job.winner))
            ) {
                job.winner = candidate;
                job.bestScore = score;
            }
        }
        job.cursor = end;
        if (end == count && job.winner != address(0)) {
            job.selected = true;
            localAllocated[job.winner] = true;
            emit RecipientSelected(nextJobId, job.winner, job.bestScore);
        }
    }
    function payJob() external nonReentrant whenActive {
        require(msg.sender == operator, "operator");
        Job storage job = localJobs[nextJobId];
        require(job.selected && !job.paid, "job");
        job.paid = true;
        imd.safeTransfer(paymentRecipient, jobBudget);
        emit JobPayment(nextJobId, jobBudget, paymentRecipient);
    }
    function bindRequest(bytes32 requestId) external whenActive {
        require(msg.sender == operator && requestId != bytes32(0), "operator");
        Job storage job = localJobs[nextJobId];
        require(job.selected && job.paid && job.requestId == bytes32(0), "job");
        require(!usedRequests(requestId), "request already used");
        localUsedRequests[requestId] = true;
        job.requestId = requestId;
        emit WorkRequested(nextJobId, requestId);
    }
    function submit(
        bytes calldata art,
        uint16 durationMs,
        uint8 effect,
        bytes calldata proof
    ) external nonReentrant whenActive {
        require(msg.sender == operator, "operator");
        uint256 id = nextJobId;
        Job storage job = localJobs[id];
        require(job.selected && job.paid && job.requestId != bytes32(0), "job");
        bytes32 hash = sha256(art);
        if (id == 1) require(hash == baseHash && effect == 0 && durationMs == 0, "base");
        require(
            verifier.verify(id, job.requestId, sha256(abi.encode(art, durationMs, effect)), proof),
            "artifact proof"
        );
        nextJobId = id + 1;
        require(collection.commitAndMint(job.winner, art, durationMs, effect) == id, "mint order");
        emit JobMinted(id, job.requestId, hash);
        if (id == 1000) {
            uint256 surplus = imd.balanceOf(address(this));
            if (surplus > 0) {
                address destination = address(collection.rewards());
                imd.forceApprove(destination, surplus);
                ICompletionRewards(destination).fund(surplus);
            }
        }
    }
    function renounceOwnership() public override onlyOwner { revert("ownership required"); }
}

contracts/FeeRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {CreationController} from "./CreationController.sol";
import {RewardsDistributor} from "./RewardsDistributor.sol";
interface IFeeHook { function router() external view returns(address); }
contract FeeRouter is Ownable2Step, ReentrancyGuard {
    using SafeERC20 for IERC20;
    IERC20 public immutable imd;
    CreationController public creation;
    RewardsDistributor public immutable rewards;
    address public immutable protocolRecipient;
    address public hook;
    uint256 public constant MIGRATION_DELAY = 2 days;
    CreationController public pendingController;
    bytes32 public pendingCodeHash;
    uint256 public migrationAvailableAt;
    uint256 public migrationEscrow;
    event ControllerMigrationScheduled(
        address indexed oldController,
        address indexed newController,
        uint256 availableAt
    );
    event ControllerMigrationCancelled();
    event ControllerMigrated(
        address indexed oldController,
        address indexed newController,
        uint256 forwardedEscrow
    );
    event FeesRouted(
        uint256 grossImd,
        uint256 creationOrRewards,
        uint256 protocol,
        bool rewardPhase
    );
    constructor(
        address admin,
        IERC20 money,
        CreationController controller,
        RewardsDistributor distributor,
        address protocol
    ) Ownable(admin) {
        require(
            protocol != address(0) &&
                address(money).code.length > 0 &&
                address(controller).code.length > 0 &&
                address(distributor).code.length > 0,
            "configuration"
        );
        require(
            address(controller.imd()) == address(money) &&
                address(distributor.imd()) == address(money) &&
                address(distributor.collection()) == address(controller.collection()),
            "fee links"
        );
        imd = money;
        creation = controller;
        rewards = distributor;
        protocolRecipient = protocol;
        money.forceApprove(address(controller), type(uint256).max);
        money.forceApprove(address(distributor), type(uint256).max);
    }
    function configureHook(address value) external onlyOwner {
        require(hook == address(0) && value.code.length > 0 && IFeeHook(value).router() == address(this), "hook");
        hook = value;
    }
    function scheduleControllerMigration(CreationController replacement) external onlyOwner {
        require(
            address(pendingController) == address(0) &&
                replacement.owner() == owner() &&
                replacement.feeRouter() == address(this) &&
                address(replacement.predecessor()) == address(creation) &&
                replacement.paused() &&
                !replacement.migrationImported() &&
                creation.paused() &&
                creation.collection().totalSupply() < 1000,
            "migration state"
        );
        pendingController = replacement;
        pendingCodeHash = address(replacement).codehash;
        migrationAvailableAt = block.timestamp + MIGRATION_DELAY;
        emit ControllerMigrationScheduled(
            address(creation),
            address(replacement),
            migrationAvailableAt
        );
    }
    function cancelControllerMigration() external onlyOwner {
        require(address(pendingController) != address(0), "no migration");
        pendingController = CreationController(address(0));
        migrationAvailableAt = 0;
        pendingCodeHash = bytes32(0);
        emit ControllerMigrationCancelled();
    }
    function executeControllerMigration() external onlyOwner nonReentrant {
        CreationController next = pendingController;
        CreationController previous = creation;
        require(
            address(next) != address(0) &&
                block.timestamp >= migrationAvailableAt &&
                address(next).codehash == pendingCodeHash &&
                previous.retired() &&
                address(next.predecessor()) == address(previous),
            "migration delay or state"
        );
        next.importMigration();
        previous.collection().replaceController(address(next));
        imd.forceApprove(address(previous), 0);
        imd.forceApprove(address(next), type(uint256).max);
        creation = next;
        pendingController = CreationController(address(0));
        migrationAvailableAt = 0;
        pendingCodeHash = bytes32(0);
        next.activateMigration();
        uint256 escrow = migrationEscrow;
        migrationEscrow = 0;
        if (escrow > 0) next.deposit(escrow);
        emit ControllerMigrated(address(previous), address(next), escrow);
    }
    function routeAmounts(uint256 allocation, uint256 protocol) external nonReentrant {
        require(msg.sender == hook, "hook");
        distribute(0, allocation, protocol);
    }
    function distribute(uint256 grossImd, uint256 allocation, uint256 protocol) private {
        uint256 fee = allocation + protocol;
        if (fee == 0) return;
        uint256 balance = imd.balanceOf(address(this));
        imd.safeTransferFrom(msg.sender, address(this), fee);
        require(imd.balanceOf(address(this)) - balance == fee, "received");
        bool completed = creation.collection().totalSupply() == 1000;
        if (allocation > 0) {
            if (completed) rewards.fund(allocation);
            else if (creation.retired()) migrationEscrow += allocation;
            else creation.deposit(allocation);
        }
        if (protocol > 0) imd.safeTransfer(protocolRecipient, protocol);
        emit FeesRouted(grossImd, allocation, protocol, completed);
    }
    function renounceOwnership() public override onlyOwner { revert("ownership required"); }
}

contracts/HookFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
contract HookFactory {
    address public immutable deployer;
    event HookDeployed(address indexed hook, bytes32 salt);
    constructor(address establishedWallet) {
        require(establishedWallet != address(0), "deployer");
        deployer = establishedWallet;
    }
    function deploy(bytes32 salt, bytes calldata initCode) external returns (address result) {
        require(msg.sender == deployer, "deployer");
        bytes memory code = initCode;
        assembly {
            result := create2(0, add(code, 32), mload(code), salt)
        }
        require(result != address(0), "deployment");
        emit HookDeployed(result, salt);
    }
}

contracts/IMDCreationController.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";

import {SwarmCollection} from "./SwarmCollection.sol";
interface IIMDArtifactVerifier {
    function attestor() external view returns (address);
    function verify(
        uint256 id,
        bytes32 requestId,
        bytes32 hash,
        bytes calldata proof
    ) external view returns (bool);
    function verifyFinality(uint256 cutoff, bytes calldata proof) external view returns (bool);
    function verifySelection(bytes32 payloadHash, bytes calldata proof) external view returns(bool);
    function verifyRecovery(
        uint256 id,
        bytes32 requestId,
        uint256 attempt,
        uint256 amount,
        address paymentRecipient,
        bytes calldata proof
    ) external view returns (bool);
}
interface IIMDCompletionRewards {
    function fund(uint256 amount) external;
}
contract IMDCreationController is Ownable2Step, ReentrancyGuard {
    using SafeERC20 for IERC20;
    struct Funding {
        uint256 cumulative;
        uint64 blockNumber;
        uint64 time;
    }
    struct Job {
        uint64 cutoff;
        uint64 time;
        uint256 cursor;
        uint256 count;
        address winner;
        uint256 bestScore;
        bytes32 requestId;
        bool selected;
        bool paid;
        bool finalized;
    }
    IERC20 public immutable imd;
    IERC20 public token;
    uint256 public scoringStartBlock;
    bool public eligibilitySealed;
    bytes32 public rulesHash;
    uint256 public selectionNonce;
    mapping(uint256 => bytes32) public cutoffHashes;
    mapping(uint256 => bool) public emptySnapshot;
    mapping(address => bool) public excluded;
    address[] private exclusions;
    uint256 public constant MINIMUM_HOLDER_BALANCE = 10_000 ether;
    event TokenConfigured(address indexed token, uint256 firstMintBlock);
    event EligibilitySealed(bytes32 rulesHash);
    function exclusionList() external view returns(address[] memory) { return exclusions; }
    function configureToken(IERC20 project, uint256 firstMintBlock) external onlyOwner {
        require(address(token) == address(0) && address(project).code.length > 0 && firstMintBlock > 0 && firstMintBlock <= block.number, "token configuration");
        require(project.totalSupply() == 1_000_000_000 ether && IERC20Metadata(address(project)).decimals() == 18, "standard supply");
        token = project; scoringStartBlock = firstMintBlock;
        emit TokenConfigured(address(project), firstMintBlock);
    }
    function addExclusion(address account) external onlyOwner {
        require(!eligibilitySealed && account != address(0) && exclusions.length < 512, "exclusions sealed or invalid");
        if (!excluded[account]) { excluded[account] = true; exclusions.push(account); }
    }
    function sealEligibility() external onlyOwner {
        require(!eligibilitySealed && address(token) != address(0) && feeRouter != address(0), "configuration incomplete");
        require(excluded[owner()] && excluded[operator] && excluded[feeRouter] && excluded[address(collection)] && excluded[address(verifier)], "protocol exclusions required");
        rulesHash = keccak256(abi.encode(keccak256("IMPEPE lifetime token-seconds, cutoff minimum 10000, lower-address ties, one original per wallet v1"), address(token), scoringStartBlock, MINIMUM_HOLDER_BALANCE, keccak256(abi.encode(exclusions))));
        eligibilitySealed = true; emit EligibilitySealed(rulesHash);
    }
    SwarmCollection public immutable collection;
    IIMDArtifactVerifier public immutable verifier;
    address public immutable operator;
    address public immutable paymentRecipient;
    uint256 public immutable jobBudget;
    uint256 public immutable settlementBlocks;
    bytes32 public immutable baseHash;
    address public immutable recoveryRecipient;
    uint256 public constant MIGRATION_DELAY = 2 days;
    bool public paused;
    bool public retired;
    uint256 public withdrawalAvailableAt;
    bytes32 public withdrawalReason;
    uint256 public totalFunded;
    uint256 public nextJobId = 1;
    address public feeRouter;
    Funding[] private localFunding;
    IMDCreationController public predecessor;
    uint256 public inheritedFundingCount;
    uint256 public migrationStartId;
    uint256 public migrationDepth;
    bool public migrationImported;
    uint256 public recoveredAmount;
    mapping(uint256 => Job) private localJobs;
    mapping(address => bool) private localAllocated;
    mapping(bytes32 => bool) private localUsedRequests;
    mapping(uint256 => uint256) public attempts;
    mapping(uint256 => uint256) private localFundingIndex;
    function fundingIndex(uint256 id) public view returns(uint256) {
        if (id < migrationStartId && address(predecessor) != address(0)) return predecessor.fundingIndex(id);
        return localFundingIndex[id];
    }
    event CreationFunded(uint256 amount, uint256 cumulative);
    event JobOpened(uint256 indexed id, uint256 cutoff, uint256 time);
    event RecipientSelected(uint256 indexed id, address indexed winner, uint256 score);
    event JobPayment(uint256 indexed id, uint256 amount, address recipient);
    event WorkRequested(uint256 indexed id, bytes32 requestId);
    event JobMinted(uint256 indexed id, bytes32 requestId, bytes32 artifactHash);
    event JobRecovered(
        uint256 indexed id,
        bytes32 oldRequestId,
        uint256 attempt,
        uint256 refundedBudget,
        address refundPayer
    );
    event SnapshotAdvanced(uint256 indexed id, uint256 oldCutoff, uint256 newCutoff);
    event EmergencyPaused(address indexed administrator);
    event CreationResumed();
    event WithdrawalScheduled(address indexed recipient, uint256 availableAt, bytes32 reason);
    event WithdrawalCancelled();
    event CreationFundsRecovered(address indexed recipient, uint256 amount, bytes32 reason);
    modifier whenActive() {
        require(
            !paused && !retired && (address(predecessor) == address(0) || migrationImported),
            "creation paused or retired"
        );
        _;
    }
    constructor(
        address admin,
        IERC20 money,
        SwarmCollection nft,
        IIMDArtifactVerifier proofVerifier,
        address swarmOperator,
        address payTo,
        uint256 budget,
        uint256 delayBlocks,
        bytes32 firstArtHash
    ) Ownable(admin) {
        require(
            address(money) != address(0) &&
                address(nft) != address(0) &&
                address(proofVerifier) != address(0),
            "contracts"
        );
        address signer = proofVerifier.attestor();
        require(
            signer != address(0) && signer != swarmOperator && signer != admin,
            "independent attestor required"
        );
        require(
            swarmOperator != address(0) &&
                swarmOperator != admin &&
                payTo != address(0) &&
                budget > 0 &&
                delayBlocks > 0 &&
                firstArtHash != bytes32(0),
            "configuration"
        );
        imd = money;
        collection = nft;
        verifier = proofVerifier;
        operator = swarmOperator;
        paymentRecipient = payTo;
        jobBudget = budget;
        settlementBlocks = delayBlocks;
        baseHash = firstArtHash;
        recoveryRecipient = admin;
    }
    // Creation reserves only. Already allocated NFT rewards and pool liquidity are outside this contract.
    function emergencyPause() external onlyOwner {
        require(!paused && !retired && collection.totalSupply() < 1000, "creation phase");
        paused = true;
        emit EmergencyPaused(msg.sender);
    }
    function resumeCreation() external onlyOwner {
        require(
            paused &&
                !retired &&
                withdrawalAvailableAt == 0 &&
                (address(predecessor) == address(0) ||
                    (migrationImported && collection.controller() == address(this))),
            "migration pending or retired"
        );
        paused = false;
        emit CreationResumed();
    }
    function scheduleWithdrawal(bytes32 reason) external onlyOwner {
        require(
            paused && !retired && withdrawalAvailableAt == 0 && reason != bytes32(0),
            "withdrawal state"
        );
        withdrawalAvailableAt = block.timestamp + MIGRATION_DELAY;
        withdrawalReason = reason;
        emit WithdrawalScheduled(recoveryRecipient, withdrawalAvailableAt, reason);
    }
    function cancelWithdrawal() external onlyOwner {
        require(!retired && withdrawalAvailableAt != 0, "no pending withdrawal");
        withdrawalAvailableAt = 0;
        withdrawalReason = bytes32(0);
        emit WithdrawalCancelled();
    }
    function withdrawCreationFunds() external onlyOwner nonReentrant {
        require(
            paused &&
                !retired &&
                withdrawalAvailableAt != 0 &&
                block.timestamp >= withdrawalAvailableAt &&
                collection.totalSupply() < 1000,
            "withdrawal delay or phase"
        );
        retired = true;
        uint256 amount = imd.balanceOf(address(this));
        recoveredAmount = amount;
        imd.safeTransfer(recoveryRecipient, amount);
        emit CreationFundsRecovered(recoveryRecipient, amount, withdrawalReason);
    }
    event MigrationPrepared(address indexed predecessor);
    event MigrationImported(address indexed predecessor, uint256 nextNft, uint256 recoveredFunds);
    function allocated(address account) public view returns (bool) {
        return
            localAllocated[account] ||
            (address(predecessor) != address(0) && predecessor.allocated(account));
    }
    function usedRequests(bytes32 request) public view returns (bool) {
        return
            localUsedRequests[request] ||
            (address(predecessor) != address(0) && predecessor.usedRequests(request));
    }
    function jobs(uint256 id) external view returns (Job memory) {
        if (address(predecessor) != address(0) && migrationImported && id < migrationStartId)
            return predecessor.jobs(id);
        return localJobs[id];
    }
    function fundingLength() public view returns (uint256) {
        return inheritedFundingCount + localFunding.length;
    }
    function funding(uint256 index) public view returns (Funding memory) {
        if (index < inheritedFundingCount) return predecessor.funding(index);
        return localFunding[index - inheritedFundingCount];
    }
    // A replacement is inert until the official fee router completes its delayed atomic handover.
    function prepareMigration(IMDCreationController previous) external onlyOwner {
        require(
            address(predecessor) == address(0) &&
                totalFunded == 0 &&
                nextJobId == 1 &&
                localFunding.length == 0 &&
                address(previous) != address(this),
            "fresh replacement"
        );
        require(
            previous.paused() &&
                address(previous.token()) == address(token) &&
                address(previous.collection()) == address(collection) &&
                address(previous.imd()) == address(imd) &&
                previous.recoveryRecipient() == recoveryRecipient &&
                previous.operator() == operator &&
                previous.paymentRecipient() == paymentRecipient &&
                previous.jobBudget() == jobBudget &&
                previous.settlementBlocks() == settlementBlocks &&
                previous.baseHash() == baseHash &&
                (rulesHash == bytes32(0) || previous.rulesHash() == rulesHash) && previous.scoringStartBlock() == scoringStartBlock &&
                previous.migrationDepth() < 8,
            "migration compatibility"
        );
        require(
            collection.totalSupply() < 1000 && collection.controller() == address(previous),
            "current controller"
        );
        predecessor = previous;
        require(!eligibilitySealed && exclusions.length == 0 && previous.eligibilitySealed(), "fresh migration rules");
        address[] memory inheritedExclusions = previous.exclusionList();
        for(uint256 i; i < inheritedExclusions.length; i++) { exclusions.push(inheritedExclusions[i]); excluded[inheritedExclusions[i]] = true; }
        rulesHash = previous.rulesHash();
        eligibilitySealed = true;
        migrationDepth = previous.migrationDepth() + 1;
        paused = true;
        emit MigrationPrepared(address(previous));
    }
    function importMigration() external nonReentrant {
        require(
            msg.sender == feeRouter &&
                paused &&
                !retired &&
                address(predecessor) != address(0) &&
                !migrationImported &&
                predecessor.retired() &&
                collection.controller() == address(predecessor),
            "migration import"
        );
        nextJobId = predecessor.nextJobId();
        require(nextJobId == collection.totalSupply() + 1, "mint sequence");
        totalFunded = predecessor.totalFunded();
        inheritedFundingCount = predecessor.fundingLength();
        migrationStartId = nextJobId;
        localJobs[nextJobId] = predecessor.jobs(nextJobId);
        attempts[nextJobId] = predecessor.attempts(nextJobId);
        selectionNonce = predecessor.selectionNonce();
        cutoffHashes[nextJobId] = predecessor.cutoffHashes(nextJobId);
        emptySnapshot[nextJobId] = predecessor.emptySnapshot(nextJobId);
        localFundingIndex[nextJobId] = predecessor.fundingIndex(nextJobId);
        uint256 amount = predecessor.recoveredAmount();
        uint256 balance = imd.balanceOf(address(this));
        if (amount > 0) imd.safeTransferFrom(recoveryRecipient, address(this), amount);
        require(imd.balanceOf(address(this)) - balance == amount, "full migration funding");
        migrationImported = true;
        emit MigrationImported(address(predecessor), nextJobId, amount);
    }
    function activateMigration() external {
        require(
            msg.sender == feeRouter &&
                migrationImported &&
                paused &&
                !retired &&
                withdrawalAvailableAt == 0 &&
                collection.controller() == address(this),
            "migration activation"
        );
        paused = false;
        emit CreationResumed();
    }
    function configureRouter(address router) external onlyOwner {
        require(feeRouter == address(0) && router.code.length > 0, "router");
        feeRouter = router;
    }
    function deposit(uint256 amount) external nonReentrant {
        require(
            msg.sender == feeRouter &&
                eligibilitySealed &&
                collection.totalSupply() < 1000 &&
                amount > 0,
            "funding"
        );
        require(
            !retired && (address(predecessor) == address(0) || migrationImported),
            "retired or inert controller"
        );
        uint256 beforeBalance = imd.balanceOf(address(this));
        imd.safeTransferFrom(msg.sender, address(this), amount);
        require(imd.balanceOf(address(this)) - beforeBalance == amount, "received");
        totalFunded += amount;
        localFunding.push(Funding(totalFunded, uint64(block.number), uint64(block.timestamp)));
        emit CreationFunded(amount, totalFunded);
    }
    // Anyone can open/scan. The cutoff is the earliest funding checkpoint meeting this job's cumulative budget.
    function openNextJob() external whenActive {
        uint256 id = nextJobId;
        require(id <= 1000 && localJobs[id].cutoff == 0 && totalFunded >= id * jobBudget, "job");
        uint256 lo = id > 1 ? fundingIndex(id - 1) : 0;
        uint256 hi = fundingLength();
        while (lo < hi) {
            uint256 mid = (lo + hi) / 2;
            if (funding(mid).cumulative < id * jobBudget) lo = mid + 1;
            else hi = mid;
        }
        Funding memory point = funding(lo);
        localFundingIndex[id] = lo;
        localJobs[id].cutoff = point.blockNumber;
        localJobs[id].time = point.time;
        emit JobOpened(id, point.blockNumber, point.time);
    }
    function confirmFinality(bytes calldata proof) external whenActive {
        Job storage job = localJobs[nextJobId];
        require(
            job.cutoff > 0 &&
                !job.finalized &&
                block.number > uint256(job.cutoff) + settlementBlocks,
            "settlement"
        );
        require(verifier.verifyFinality(job.cutoff, proof), "finality proof");
        (bytes32 cutoffHash,,) = abi.decode(proof, (bytes32,uint256,bytes));
        cutoffHashes[nextJobId] = cutoffHash;
        job.finalized = true;
    }
    // An exhausted snapshot can move only to the earliest later funding block, never to an arbitrary cutoff.
    function advanceEmptySnapshot() external whenActive {
        uint256 id = nextJobId;
        Job storage job = localJobs[id];
        require(
            job.cutoff > 0 &&
                job.finalized &&
                !job.selected &&
                job.winner == address(0) &&
                emptySnapshot[id],
            "snapshot not exhausted"
        );
        uint256 lo = localFundingIndex[id] + 1;
        uint256 hi = fundingLength();
        while (lo < hi) {
            uint256 mid = (lo + hi) / 2;
            if (funding(mid).blockNumber <= job.cutoff) lo = mid + 1;
            else hi = mid;
        }
        require(lo < fundingLength(), "await next funding snapshot");
        Funding memory point = funding(lo);
        uint256 old = job.cutoff;
        localFundingIndex[id] = lo;
        job.cutoff = point.blockNumber;
        job.time = point.time;
        job.cursor = 0;
        job.count = 0;
        job.bestScore = 0;
        emptySnapshot[id] = false;
        cutoffHashes[id] = bytes32(0);
        job.finalized = false;
        emit SnapshotAdvanced(id, old, point.blockNumber);
        emit JobOpened(id, point.blockNumber, point.time);
    }
    // Replacement authorization is bound to this exact attempt, and another budget must be returned first.
    function recoverJob(bytes calldata proof) external nonReentrant {
        require(!retired, "retired controller");
        uint256 id = nextJobId;
        Job storage job = localJobs[id];
        require(id <= 1000 && job.selected && job.paid, "paid job required");
        uint256 attempt = attempts[id];
        bytes32 oldRequest = job.requestId;
        require(
            verifier.verifyRecovery(id, oldRequest, attempt, jobBudget, paymentRecipient, proof),
            "recovery proof"
        );
        uint256 beforeBalance = imd.balanceOf(address(this));
        imd.safeTransferFrom(msg.sender, address(this), jobBudget);
        require(imd.balanceOf(address(this)) - beforeBalance == jobBudget, "full refund required");
        attempts[id] = attempt + 1;
        job.paid = false;
        job.requestId = bytes32(0);
        emit JobRecovered(id, oldRequest, attempt + 1, jobBudget, msg.sender);
    }
    // Independent signer attests a complete historical ranking; this is not a native cryptographic ranking proof.
    function selectRecipient(address winner, uint256 balance, uint256 score, bytes calldata proof) external whenActive {
        uint256 id = nextJobId;
        Job storage job = localJobs[id];
        require(eligibilitySealed && job.finalized && !job.selected && !emptySnapshot[id], "selection state");
        require(job.cutoff >= scoringStartBlock && cutoffHashes[id] != bytes32(0), "cutoff");
        bytes32 payload = keccak256(abi.encode(address(token), id, job.cutoff, cutoffHashes[id], job.time, selectionNonce, rulesHash, winner, balance, score));
        require(verifier.verifySelection(payload, proof), "selection proof");
        selectionNonce++;
        if (winner == address(0)) {
            require(balance == 0 && score == 0, "empty selection");
            emptySnapshot[id] = true;
            return;
        }
        require(balance >= MINIMUM_HOLDER_BALANCE && !excluded[winner] && !allocated(winner) && winner != address(this) && winner != address(token) && winner != address(imd) && winner != feeRouter && winner != address(verifier) && winner != address(collection.rewards()), "ineligible recipient");
        job.winner = winner; job.bestScore = score; job.selected = true;
        localAllocated[winner] = true;
        emit RecipientSelected(id, winner, score);
    }
    function payJob() external nonReentrant whenActive {
        require(msg.sender == operator, "operator");
        Job storage job = localJobs[nextJobId];
        require(job.selected && !job.paid, "job");
        job.paid = true;
        imd.safeTransfer(paymentRecipient, jobBudget);
        emit JobPayment(nextJobId, jobBudget, paymentRecipient);
    }
    function bindRequest(bytes32 requestId) external whenActive {
        require(msg.sender == operator && requestId != bytes32(0), "operator");
        Job storage job = localJobs[nextJobId];
        require(job.selected && job.paid && job.requestId == bytes32(0), "job");
        require(!usedRequests(requestId), "request already used");
        localUsedRequests[requestId] = true;
        job.requestId = requestId;
        emit WorkRequested(nextJobId, requestId);
    }
    function submit(
        bytes calldata art,
        uint16 durationMs,
        uint8 effect,
        bytes calldata proof
    ) external nonReentrant whenActive {
        require(msg.sender == operator, "operator");
        uint256 id = nextJobId;
        Job storage job = localJobs[id];
        require(job.selected && job.paid && job.requestId != bytes32(0), "job");
        bytes32 hash = sha256(art);
        if (id == 1) require(hash == baseHash && effect == 0 && durationMs == 0, "base");
        require(
            verifier.verify(id, job.requestId, sha256(abi.encode(art, durationMs, effect)), proof),
            "artifact proof"
        );
        nextJobId = id + 1;
        require(collection.commitAndMint(job.winner, art, durationMs, effect) == id, "mint order");
        emit JobMinted(id, job.requestId, hash);
        if (id == 1000) {
            uint256 surplus = imd.balanceOf(address(this));
            if (surplus > 0) {
                address destination = address(collection.rewards());
                imd.forceApprove(destination, surplus);
                IIMDCompletionRewards(destination).fund(surplus);
            }
        }
    }
    function renounceOwnership() public override onlyOwner { revert("ownership required"); }
}

contracts/IMDFeeRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IMDCreationController} from "./IMDCreationController.sol";
import {RewardsDistributor} from "./RewardsDistributor.sol";
interface IIMDFeeHook { function router() external view returns(address); function project() external view returns(address); function imd() external view returns(address); }
contract IMDFeeRouter is Ownable2Step, ReentrancyGuard {
    using SafeERC20 for IERC20;
    IERC20 public immutable imd;
    IMDCreationController public creation;
    RewardsDistributor public immutable rewards;
    address public hook;
    uint256 public constant MIGRATION_DELAY = 2 days;
    IMDCreationController public pendingController;
    bytes32 public pendingCodeHash;
    uint256 public migrationAvailableAt;
    uint256 public migrationEscrow;
    event ControllerMigrationScheduled(
        address indexed oldController,
        address indexed newController,
        uint256 availableAt
    );
    event ControllerMigrationCancelled();
    event ControllerMigrated(
        address indexed oldController,
        address indexed newController,
        uint256 forwardedEscrow
    );
    event FeesRouted(
        uint256 grossImd,
        uint256 creationOrRewards,
        uint256 protocol,
        bool rewardPhase
    );
    constructor(
        address admin,
        IERC20 money,
        IMDCreationController controller,
        RewardsDistributor distributor
    ) Ownable(admin) {
        require(
                address(money).code.length > 0 &&
                address(controller).code.length > 0 &&
                address(distributor).code.length > 0,
            "configuration"
        );
        require(
            address(controller.imd()) == address(money) &&
                address(distributor.imd()) == address(money) &&
                address(distributor.collection()) == address(controller.collection()),
            "fee links"
        );
        imd = money;
        creation = controller;
        rewards = distributor;
        money.forceApprove(address(controller), type(uint256).max);
        money.forceApprove(address(distributor), type(uint256).max);
    }
    function configureHook(address value) external onlyOwner {
        require(hook == address(0) && value.code.length > 0 && IIMDFeeHook(value).router() == address(this) && IIMDFeeHook(value).project() == address(creation.token()) && IIMDFeeHook(value).imd() == address(imd), "hook");
        hook = value;
    }
    function scheduleControllerMigration(IMDCreationController replacement) external onlyOwner {
        require(
            address(pendingController) == address(0) &&
                replacement.owner() == owner() &&
                replacement.feeRouter() == address(this) &&
                address(replacement.predecessor()) == address(creation) &&
                replacement.paused() &&
                !replacement.migrationImported() &&
                creation.paused() &&
                creation.collection().totalSupply() < 1000,
            "migration state"
        );
        pendingController = replacement;
        pendingCodeHash = address(replacement).codehash;
        migrationAvailableAt = block.timestamp + MIGRATION_DELAY;
        emit ControllerMigrationScheduled(
            address(creation),
            address(replacement),
            migrationAvailableAt
        );
    }
    function cancelControllerMigration() external onlyOwner {
        require(address(pendingController) != address(0), "no migration");
        pendingController = IMDCreationController(address(0));
        migrationAvailableAt = 0;
        pendingCodeHash = bytes32(0);
        emit ControllerMigrationCancelled();
    }
    function executeControllerMigration() external onlyOwner nonReentrant {
        IMDCreationController next = pendingController;
        IMDCreationController previous = creation;
        require(
            address(next) != address(0) &&
                block.timestamp >= migrationAvailableAt &&
                address(next).codehash == pendingCodeHash &&
                previous.retired() &&
                address(next.predecessor()) == address(previous),
            "migration delay or state"
        );
        next.importMigration();
        previous.collection().replaceController(address(next));
        imd.forceApprove(address(previous), 0);
        imd.forceApprove(address(next), type(uint256).max);
        creation = next;
        pendingController = IMDCreationController(address(0));
        migrationAvailableAt = 0;
        pendingCodeHash = bytes32(0);
        next.activateMigration();
        uint256 escrow = migrationEscrow;
        migrationEscrow = 0;
        if (escrow > 0) next.deposit(escrow);
        emit ControllerMigrated(address(previous), address(next), escrow);
    }
    function routeAmount(uint256 allocation) external nonReentrant {
        require(msg.sender == hook, "hook");
        if (allocation == 0) return;
        uint256 balance = imd.balanceOf(address(this));
        imd.safeTransferFrom(msg.sender, address(this), allocation);
        require(imd.balanceOf(address(this)) - balance == allocation, "received");
        bool completed = creation.collection().totalSupply() == 1000;
        if (completed) rewards.fund(allocation);
        else if (creation.retired()) migrationEscrow += allocation;
        else creation.deposit(allocation);
        emit FeesRouted(0, allocation, 0, completed);
    }
    function renounceOwnership() public override onlyOwner { revert("ownership required"); }
}

contracts/IMDLaunchHook.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IHooks} from "@uniswap/v4-core/src/interfaces/IHooks.sol";
import {Hooks} from "@uniswap/v4-core/src/libraries/Hooks.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {SwapParams, ModifyLiquidityParams} from "@uniswap/v4-core/src/types/PoolOperation.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";
import {BalanceDelta, BalanceDeltaLibrary} from "@uniswap/v4-core/src/types/BalanceDelta.sol";
import {BeforeSwapDelta, toBeforeSwapDelta} from "@uniswap/v4-core/src/types/BeforeSwapDelta.sol";
import {IMDFeeRouter} from "./IMDFeeRouter.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
contract IMDLaunchHook is ReentrancyGuard {
    using SafeERC20 for IERC20;
    using BalanceDeltaLibrary for BalanceDelta;
    IPoolManager public immutable manager;
    address public immutable imd;
    address public immutable project;
    IMDFeeRouter public immutable router;
    int24 public immutable spacing;
    address public immutable launchFactory;
    uint24 public constant POOL_FEE = 12500;
    uint256 public constant HOOK_FEE_BPS = 300;
    uint256 public pendingCreation;
    bool private flushing;
    event FeesAccrued(uint256 grossImd, uint256 allocation, uint256 protocol);
    function accrue(uint256 gross, uint256 fee) private {
        uint256 allocation = fee;
        pendingCreation += allocation;
        manager.mint(address(this), uint256(uint160(imd)), fee);
        emit FeesAccrued(gross, allocation, 0);
    }
    function flushFees() external nonReentrant {
        uint256 allocation = pendingCreation;
        if (allocation == 0) return;
        pendingCreation = 0;
        flushing = true;
        manager.unlock(abi.encode(allocation));
        flushing = false;
        router.routeAmount(allocation);
    }
    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        require(msg.sender == address(manager) && flushing, "fee settlement only");
        uint256 amount = abi.decode(data, (uint256));
        manager.burn(address(this), uint256(uint160(imd)), amount);
        manager.take(Currency.wrap(imd), address(this), amount);
        return "";
    }
    constructor(
        IPoolManager poolManager,
        address token,
        address factory,
        address money,
        IMDFeeRouter fees,
        int24 tickSpacing
    ) {
        require(
            address(poolManager).code.length > 0 && token.code.length > 0 &&
                money != token &&
                tickSpacing > 0 &&
                factory != address(0) && address(fees).code.length > 0 && address(fees.imd()) == money,
            "configuration"
        );
        manager = poolManager;
        imd = money;
        project = token;
        router = fees;
        spacing = tickSpacing;
        launchFactory = factory;
        Hooks.Permissions memory p;
        p.beforeInitialize = true;
        p.beforeAddLiquidity = true;
        p.beforeRemoveLiquidity = true;
        p.beforeSwap = true;
        p.afterSwap = true;
        p.beforeSwapReturnDelta = true;
        p.afterSwapReturnDelta = true;
        Hooks.validateHookPermissions(IHooks(address(this)), p);
        IERC20(money).forceApprove(address(fees), type(uint256).max);
    }
    modifier onlyManager() {
        require(msg.sender == address(manager), "pool manager");
        _;
    }
    function check(PoolKey calldata key) private view {
        address a = Currency.unwrap(key.currency0);
        address b = Currency.unwrap(key.currency1);
        require(
            ((a == imd && b == project) || (a == project && b == imd)) &&
                key.fee == POOL_FEE &&
                key.tickSpacing == spacing &&
                address(key.hooks) == address(this),
            "official pool only"
        );
    }
    function beforeInitialize(
        address sender,
        PoolKey calldata key,
        uint160
    ) external onlyManager returns (bytes4) {
        check(key);
        require(sender == launchFactory, "launch factory initializes pool");
        return this.beforeInitialize.selector;
    }
    function beforeAddLiquidity(
        address sender,
        PoolKey calldata key,
        ModifyLiquidityParams calldata,
        bytes calldata
    ) external onlyManager returns (bytes4) {
        check(key);
        // Liquidity may be added through the launch factory or its position manager.
        sender;
        return this.beforeAddLiquidity.selector;
    }
    function beforeRemoveLiquidity(
        address,
        PoolKey calldata key,
        ModifyLiquidityParams calldata params,
        bytes calldata
    ) external onlyManager returns (bytes4) {
        check(key);
        // v4 collects LP fees through a zero-liquidity-delta modification. Allow collection without principal withdrawal.
        require(params.liquidityDelta == 0, "liquidity permanently locked");
        return this.beforeRemoveLiquidity.selector;
    }
    function inputIsImd(
        PoolKey calldata key,
        SwapParams calldata params
    ) private view returns (bool) {
        return Currency.unwrap(params.zeroForOne ? key.currency0 : key.currency1) == imd;
    }
    function beforeSwap(
        address,
        PoolKey calldata key,
        SwapParams calldata params,
        bytes calldata
    ) external onlyManager returns (bytes4, BeforeSwapDelta, uint24) {
        check(key);
        require(
            params.amountSpecified < 0 && params.amountSpecified != type(int256).min,
            "exact input only"
        );
        if (!inputIsImd(key, params)) return (this.beforeSwap.selector, toBeforeSwapDelta(0, 0), 0);
        uint256 gross = uint256(-params.amountSpecified);
        uint256 fee = (gross * HOOK_FEE_BPS) / 10000;
        require(fee <= uint256(uint128(type(int128).max)), "fee range");
        if (fee > 0) accrue(gross, fee);
        return (this.beforeSwap.selector, toBeforeSwapDelta(int128(uint128(fee)), 0), 0);
    }
    function afterSwap(
        address,
        PoolKey calldata key,
        SwapParams calldata params,
        BalanceDelta delta,
        bytes calldata
    ) external onlyManager returns (bytes4, int128) {
        check(key);
        bool buying = inputIsImd(key, params);
        int128 actualInput = params.zeroForOne ? delta.amount0() : delta.amount1();
        uint256 grossInput = uint256(-params.amountSpecified);
        uint256 expected = buying ? grossInput - (grossInput * HOOK_FEE_BPS) / 10000 : grossInput;
        require(
            actualInput < 0 && uint256(uint128(-actualInput)) == expected,
            "partial fills unsupported"
        );
        if (buying) return (this.afterSwap.selector, 0);
        int128 output = Currency.unwrap(key.currency0) == imd ? delta.amount0() : delta.amount1();
        require(output >= 0, "output");
        uint256 gross = uint256(uint128(output));
        uint256 fee = (gross * 4) / 100;
        if (fee > 0) accrue(gross, fee);
        return (this.afterSwap.selector, int128(uint128(fee)));
    }
    fallback() external {
        revert("unsupported callback");
    }
}

