        uint256 gross = uint256(uint128(output));
        uint256 fee = (gross * 4) / 100;
        if (fee > 0) accrue(gross, fee);
        return (this.afterSwap.selector, int128(uint128(fee)));
    }
    fallback() external {
        revert("unsupported callback");
    }
}

